VALUES ('Neso Academy', 'CPP-101', 'Mastering C++ Programming: From Syntax to Memory Mastery', 'Comprehensive guide to C++ operators, OOP concepts, and systems programming', '8 weeks', '4-6 hours per week', 'en', 'Master core C++ concepts including unary and binary operators, scope resolution, and OOP principles.', 'This course covers foundational to advanced C++ programming constructs. You will master arithmetic, relational, and assignment operators, delve into the scope resolution operator, and build robust object-oriented software.', 'C++ is a high-performance general-purpose language widely used in systems programming, game development, and embedded devices. This course equips learners with deep mechanical understanding of syntax, memory, and performance.', true)
ON CONFLICT (course_id) DO UPDATE SET title = EXCLUDED.title;

INSERT INTO courses (org, course_id, title, subtitle, duration, effort, language, short_description, description, overview, is_published)
VALUES ('Neso Academy', 'ML-201', 'Foundations of Machine Learning & Predictive Modeling', 'End-to-end machine learning workflows, model architectures, and data pipelines', '10 weeks', '6-8 hours per week', 'en', 'Learn the theory and implementation of machine learning models, training pipelines, and dataset engineering.', 'Explore the history, math, and practical architectures of machine learning. Understand supervised and unsupervised learning paradigms, data splitting, model evaluation, and modern ML pipelines.', 'Machine learning powers modern AI products. This course walks through the journey from historical breakthroughs to training modern predictive models on clean dataset pipelines.', true)
ON CONFLICT (course_id) DO UPDATE SET title = EXCLUDED.title;

INSERT INTO courses (org, course_id, title, subtitle, duration, effort, language, short_description, description, overview, is_published)
VALUES ('Neso Academy', 'DSA-201', 'Data Structures & Asymptotic Algorithm Analysis', 'Master abstract data types, asymptotic efficiency, and optimal memory layouts', '10 weeks', '6-8 hours per week', 'en', 'In-depth exploration of core data structures, time complexity analysis, and performance trade-offs.', 'Understand the difference between primitive data types and Abstract Data Types (ADTs). Master big-O asymptotic analysis and learn to choose optimal data structures for high-scale computational workloads.', 'Efficient algorithms rely on intelligent data structuring. This course teaches how to analyze time and space complexity and construct high-performance data structures.', true)
ON CONFLICT (course_id) DO UPDATE SET title = EXCLUDED.title;

INSERT INTO courses (org, course_id, title, subtitle, duration, effort, language, short_description, description, overview, is_published)
VALUES ('Neso Academy', 'OOP-102', 'Object-Oriented Programming & Software Design', 'Encapsulation, static members, friend functions, and class architecture', '6 weeks', '4-6 hours per week', 'en', 'Master the principles of OOP: classes, member functions, access specifiers, and friend relationships.', 'Deep-dive into class design in C++ and Java. Explore static members, static member functions, access specifiers (public, private, protected), and friend functions.', 'Object-Oriented Programming is the foundation of modern enterprise software. Learn to model real-world domains with clean encapsulation and maintainable abstraction boundaries.', true)
ON CONFLICT (course_id) DO UPDATE SET title = EXCLUDED.title;

INSERT INTO courses (org, course_id, title, subtitle, duration, effort, language, short_description, description, overview, is_published)
VALUES ('Neso Academy', 'PY-101', 'Python Programming: Beginner to Software Engineering', 'Interpreters, data types, string operations, and modern Python workflows', '8 weeks', '4-5 hours per week', 'en', 'Learn Python from the ground up: interpreter internals, VS Code setup, core types, and string operators.', 'Step into the world of Python programming. Understand how the Python interpreter works, configure a development environment with Visual Studio Code, and master types and operations.', 'Python is the undisputed language of AI, data science, and modern backend web development. This course gives learners an intuitive yet technically rigorous start.', true)
ON CONFLICT (course_id) DO UPDATE SET title = EXCLUDED.title;

INSERT INTO course_prerequisites (course_id, prerequisite_course_id)
SELECT c1.id, c2.id FROM courses c1, courses c2
WHERE c1.course_id = 'DSA-201' AND c2.course_id = 'CPP-101'
ON CONFLICT (course_id, prerequisite_course_id) DO NOTHING;

INSERT INTO course_prerequisites (course_id, prerequisite_course_id)
SELECT c1.id, c2.id FROM courses c1, courses c2
WHERE c1.course_id = 'ML-201' AND c2.course_id = 'PY-101'
ON CONFLICT (course_id, prerequisite_course_id) DO NOTHING;

INSERT INTO course_prerequisites (course_id, prerequisite_course_id)
SELECT c1.id, c2.id FROM courses c1, courses c2
WHERE c1.course_id = 'OOP-102' AND c2.course_id = 'CPP-101'
ON CONFLICT (course_id, prerequisite_course_id) DO NOTHING;

INSERT INTO modules (course_id, title, description, order_index, is_published)
SELECT id, 'Core Module: Mastering C++ Programming: From Syntax to Memory Mastery', 'Essential learning sequence for C++', 1, true FROM courses WHERE course_id = 'CPP-101'
ON CONFLICT (course_id, order_index) DO UPDATE SET title = EXCLUDED.title;

INSERT INTO sections (module_id, title, description, order_index, is_published)
SELECT m.id, 'Arithmetic Operators in C++', 'The video introduces arithmetic operators in C++, covering unary and binary operators, examples, and important rules about division and edge cases like division by zero.

What arithmetic operators are', 1, true
FROM modules m JOIN courses c ON m.course_id = c.id
WHERE c.course_id = 'CPP-101' AND m.order_index = 1
ON CONFLICT (module_id, order_index) DO UPDATE SET title = EXCLUDED.title;

INSERT INTO section_items (section_id, title, content_type, order_index)
SELECT s.id, 'Video: Arithmetic Operators in C++', 'video', 1
FROM sections s JOIN modules m ON s.module_id = m.id JOIN courses c ON m.course_id = c.id
WHERE c.course_id = 'CPP-101' AND m.order_index = 1 AND s.order_index = 1
ON CONFLICT (section_id, order_index) DO UPDATE SET title = EXCLUDED.title;

INSERT INTO item_video_contents (section_item_id, video_url, youtube_video_id, duration_seconds)
SELECT si.id, 'https://youtu.be/1XbtijPZKUs', '1XbtijPZKUs', 600
FROM section_items si
JOIN sections s ON si.section_id = s.id
JOIN modules m ON s.module_id = m.id
JOIN courses c ON m.course_id = c.id
WHERE c.course_id = 'CPP-101' AND m.order_index = 1 AND s.order_index = 1 AND si.order_index = 1
ON CONFLICT (section_item_id) DO UPDATE SET video_url = EXCLUDED.video_url;

